  "ui.4958bbece59c": {
    "fr": "À la clôture, les dotations de la nouvelle division s’ajoutent aux reports ci-dessus. Le report salarial porte seulement sur la marge inutilisée et reste limité par le salary cap.",
    "en": "At closing, the new division allocations are added to the carryforwards above. The salary carryforward applies only to the unused margin and remains limited by the salary cap.",
    "es": "Al cierre, las dotaciones de la nueva división se suman a los reportes anteriores. El reporte salarial aplica solo al margen no utilizado y sigue limitado por el tope salarial.",
    "it": "Alla chiusura, le dotazioni della nuova divisione si aggiungono ai riporti sopra indicati. Il riporto salariale riguarda solo il margine inutilizzato e rimane limitato dal salary cap.",
    "de": "Zum Abschluss werden die Mittel der neuen Abteilung zu den obigen Vorträgen addiert. Der Gehaltsvortrag bezieht sich nur auf die ungenutzte Marge und bleibt durch die Gehaltsobergrenze begrenzt.",
    "pt": "No encerramento, as dotações da nova divisão são adicionadas aos reportes acima. O reporte salarial incide apenas sobre a margem não utilizada e continua limitado pelo teto salarial.",
    "ja": "決算時に、新しい部門の配分が上記の繰越に加わります。給与の繰越は未使用マージンのみが対象で、給与キャップによって制限されます。"
  },
  "ui.7c0b8f52e096": {
    "fr": "Les indemnités de formation vont au recrutement. Les revenus marketing versent 35 % au recrutement et 15 % aux structures. Ces recettes sont calculées et créditées à la clôture.",
    "en": "Training allowances go to recruitment. Marketing revenues allocate 35% to recruitment and 15% to structures. These revenues are calculated and credited at closing.",
    "es": "Las indemnizaciones de formación van al reclutamiento. Los ingresos de marketing destinan 35 % al reclutamiento y 15 % a las estructuras. Estos ingresos se calculan y acreditan al cierre.",
    "it": "Le indennità di formazione vanno al reclutamento. I ricavi di marketing destinano il 35 % al reclutamento e il 15 % alle strutture. Questi ricavi vengono calcolati e accreditati alla chiusura.",
    "de": "Ausbildungsgelder gehen in die Rekrutierung. Marketingeinnahmen zahlen 35 % in die Rekrutierung und 15 % in die Strukturen. Diese Einnahmen werden zum Abschluss berechnet und gutgeschrieben.",
    "pt": "As indemnizações de formação vão para o recrutamento. As receitas de marketing destinam 35 % ao recrutamento e 15 % às estruturas. Estas receitas são calculadas e creditadas no encerramento.",
    "ja": "トレーニング手当はリクルートに充てられます。マーケティング収益はリクルートに35％、体制に15％支払われます。これらの収益は決算時に計算され、計上されます。"
  },
  "ui.4c4521a3cb27": {
    "fr": "Revenus de formation déjà crédités au club · toutes saisons",
    "en": "Training revenues already credited to the club · all seasons",
    "es": "Ingresos de formación ya acreditados al club · todas las temporadas",
    "it": "Ricavi di formazione già accreditati al club · tutte le stagioni",
    "de": "Bereits dem Club gutgeschriebene Ausbildungseinnahmen · alle Saisons",
    "pt": "Receitas de formação já creditadas ao clube · todas as épocas",
    "ja": "既にクラブに計上されたトレーニング収益 · 全シーズン"
  },
  "ui.5d67711b77ca": {
    "fr": "Le budget annuel de référence couvre aussi le fonctionnement du club. Il ne constitue pas un solde supplémentaire à dépenser.",
    "en": "The reference annual budget also covers club operations. It does not constitute an additional balance to spend.",
    "es": "El presupuesto anual de referencia también cubre el funcionamiento del club. No constituye un saldo adicional para gastar.",
    "it": "Il budget annuale di riferimento copre anche il funzionamento del club. Non costituisce un saldo aggiuntivo da spendere.",
    "de": "Das jährliche Referenzbudget deckt auch den Betrieb des Clubs ab. Es stellt keinen zusätzlichen auszugebenden Saldo dar.",
    "pt": "O orçamento anual de referência cobre também o funcionamento do clube. Não constitui um saldo adicional a gastar.",
    "ja": "基準年間予算はクラブ運営もカバーします。追加で使える残高を意味するものではありません。"
  },
  "ui.92b6bca8cb06": {
    "fr": "Prix fixes des structures",
    "en": "Fixed prices of structures",
    "es": "Precios fijos de las estructuras",
    "it": "Prezzi fissi delle strutture",
    "de": "Festpreise der Strukturen",
    "pt": "Preços fixos das estruturas",
    "ja": "構造物の固定価格"
  },
  "ui.1dd11454123f": {
    "fr": "Le même prix pour les trois structures, quelle que soit la division. Chaque palier s’achète séparément.",
    "en": "The same price for the three structures, regardless of the division. Each tier is purchased separately.",
    "es": "El mismo precio para las tres estructuras, sin importar la división. Cada nivel se compra por separado.",
    "it": "Lo stesso prezzo per le tre strutture, indipendentemente dalla divisione. Ogni livello si acquista separatamente.",
    "de": "Der gleiche Preis für alle drei Strukturen, unabhängig von der Abteilung. Jede Stufe wird separat gekauft.",
    "pt": "O mesmo preço para as três estruturas, independentemente da divisão. Cada patamar é comprado separadamente.",
    "ja": "3つの構造物はいずれのディビジョンでも同じ価格です。各段階は個別に購入されます。"
  },
