  "ui.723f9876b04b": {
    "fr": "Les recrues suivent leur salaire signé jusqu’à la fin du contrat. Pour les autres joueurs, le jeu applique son barème de salaire. Un départ libère sa charge.",
    "en": "Recruits keep their signed salary until the end of the contract. For other players, the game applies its salary scale. A departure frees its charge.",
    "es": "Las incorporaciones siguen su salario firmado hasta el final del contrato. Para los demás jugadores, el juego aplica su escala salarial. Una salida libera su carga.",
    "it": "I nuovi assunti mantengono il loro stipendio firmato fino alla fine del contratto. Per gli altri giocatori, il gioco applica la propria scala salariale. Una partenza libera il suo carico.",
    "de": "Neue Spieler erhalten ihr unterzeichnetes Gehalt bis zum Ende des Vertrages. Für andere Spieler wendet das Spiel seinen Gehaltsmaßstab an. Ein Abgang befreit von der Belastung.",
    "pt": "Os recrutas mantêm o salário acordado até ao final do contrato. Para os outros jogadores, o jogo aplica a sua tabela salarial. Uma saída liberta a sua carga.",
    "ja": "新入社員は契約終了まで署名した給与を受け取ります。その他の選手については、ゲームが給与表を適用します。退団はその負担を解放します。"
  },
