  "ui.6e4e24121ca3": {
    "fr": "Chaque choix est transmis au moteur. Un joueur hors de son poste perd la cohérence collective ; le buteur et le capitaine influencent réellement les pénalités et la discipline.",
    "en": "Each choice is transmitted to the engine. A player out of position loses collective coherence; the scorer and the captain actually influence penalties and discipline.",
    "es": "Cada elección se transmite al motor. Un jugador fuera de su puesto pierde la coherencia colectiva; el goleador y el capitán influyen realmente en las penalizaciones y la disciplina.",
    "it": "Ogni scelta viene trasmessa al motore. Un giocatore fuori ruolo perde la coesione collettiva; il realizzatore e il capitano influenzano realmente le penalità e la disciplina.",
    "de": "Jede Entscheidung wird an die Maschine weitergegeben. Ein Spieler außerhalb seiner Position verliert die kollektive Kohärenz; der Torschütze und der Kapitän beeinflussen tatsächlich die Strafen und die Disziplin.",
    "pt": "Cada escolha é transmitida ao motor. Um jogador fora da sua posição perde a coerência coletiva; o marcador e o capitão influenciam realmente as penalidades e a disciplina.",
    "ja": "各選択はエンジンに伝達されます。ポジション外の選手はチームの一体感を失い、ゴールキッカーとキャプテンは実際にペナルティと規律に影響します。"
  },
