  "ui.4bb382ff1adf": {
    "fr": "Le XV, le banc, le capitaine, le buteur et le plan de jeu seront figés au coup d’envoi. Les consignes collectives resteront modifiables en direct.",
    "en": "The XV, the bench, the captain, the kicker, and the game plan will be fixed at kickoff. Collective instructions will remain editable live.",
    "es": "El XV, el banquillo, el capitán, el pateador y el plan de juego se fijarán al inicio del partido. Las instrucciones colectivas seguirán siendo modificables en directo.",
    "it": "Il XV, la panchina, il capitano, il realizzatore e il piano di gioco saranno fissati al fischio d’inizio. Le istruzioni collettive resteranno modificabili in diretta.",
    "de": "Das XV, die Ersatzbank, der Kapitän, der Torschütze und der Spielplan werden beim Anpfiff festgelegt. Die kollektiven Anweisungen bleiben live bearbeitbar.",
    "pt": "O XV, o banco, o capitão, o marcador de ensaios e o plano de jogo ficarão fixos no apito inicial. As instruções coletivas poderão ser alteradas em direto.",
    "ja": "スターティング15、ベンチ、キャプテン、キッカーおよびゲームプランは、キックオフ時に固定されます。チーム指示はリアルタイムで変更可能です。"
  },
