  "ui.166e8989a439": {
    "fr": "Glisse un doigt pour déplacer la carte, pince avec deux doigts pour zoomer.{v0}",
    "en": "Slide a finger to move the map, pinch with two fingers to zoom.{v0}",
    "es": "Desliza un dedo para mover el mapa, pellizca con dos dedos para hacer zoom.{v0}",
    "it": "Scorri con un dito per spostare la mappa, pizzica con due dita per zoomare.{v0}",
    "de": "Ziehe einen Finger, um die Karte zu verschieben, pinch mit zwei Fingern, um zu zoomen.{v0}",
    "pt": "Desliza um dedo para mover o mapa, belisca com dois dedos para ampliar.{v0}",
    "ja": "マップを移動するには指を滑らせ、ズームするには2本の指でつまむ。{v0}"
  },
  "ui.c85a272489ff": {
    "fr": "Appuie sur le terrain pour choisir la destination. Glisse le fond pour déplacer la carte.",
    "en": "Tap on the field to choose the destination. Slide the background to move the map.",
    "es": "Toca el campo para elegir el destino. Desliza el fondo para mover el mapa.",
    "it": "Tocca il campo per scegliere la destinazione. Scorri sullo sfondo per spostare la mappa.",
    "de": "Tippe auf das Feld, um das Ziel auszuwählen. Ziehe den Hintergrund, um die Karte zu verschieben.",
    "pt": "Toca no campo para escolher o destino. Desliza o fundo para mover o mapa.",
    "ja": "目的地を選ぶにはフィールドをタップ。マップを移動するには背景をスライド。"
  },
  "ui.bfbcb941ddbb": {
    "fr": "Appuie sur le joueur qui doit recevoir cette passe. Glisse pour déplacer la carte.",
    "en": "Tap the player who should receive this pass. Slide to move the map.",
    "es": "Toca al jugador que debe recibir este pase. Desliza para mover el mapa.",
    "it": "Tocca il giocatore che deve ricevere questo passaggio. Scorri per spostare la mappa.",
    "de": "Tippe auf den Spieler, der diesen Pass empfangen soll. Ziehe, um die Karte zu verschieben.",
    "pt": "Toca no jogador que deve receber este passe. Desliza para mover o mapa.",
    "ja": "このパスを受けるプレーヤーをタップ。マップを移動するにはスライド。"
  },
  "ui.ff120b119f29": {
    "fr": "Choisis un geste de cette étape pour le modifier. Glisse le fond pour déplacer la carte.",
    "en": "Choose a gesture from this step to modify it. Slide the background to move the map.",
    "es": "Elige un gesto de este paso para modificarlo. Desliza el fondo para mover el mapa.",
    "it": "Scegli un gesto di questa fase per modificarlo. Scorri sullo sfondo per spostare la mappa.",
    "de": "Wähle eine Bewegung aus diesem Schritt, um sie zu ändern. Ziehe den Hintergrund, um die Karte zu verschieben.",
    "pt": "Escolhe um gesto desta etapa para o modificar. Desliza o fundo para mover o mapa.",
    "ja": "このステップのジェスチャーを選んで変更。マップを移動するには背景をスライド。"
  },
  "ui.ee305055c495": {
    "fr": "Glisse un joueur pour le placer, ou appuie sur le terrain. Glisse le fond pour déplacer la carte ; pince avec deux doigts pour zoomer.",
    "en": "Slide a player to place him, or tap on the field. Slide the background to move the map; pinch with two fingers to zoom.",
    "es": "Desliza un jugador para colocarlo, o toca el campo. Desliza el fondo para mover el mapa; pellizca con dos dedos para hacer zoom.",
    "it": "Trascina un giocatore per posizionarlo, o tocca il campo. Trascina lo sfondo per spostare la mappa; pizzica con due dita per zoomare.",
    "de": "Ziehe einen Spieler, um ihn zu platzieren, oder tippe auf das Feld. Ziehe den Hintergrund, um die Karte zu verschieben; führe eine Zwei-Finger-Zoomgeste aus, um zu zoomen.",
    "pt": "Desliza um jogador para o colocar, ou toca no campo. Desliza o fundo para mover o mapa; pinça com dois dedos para fazer zoom.",
    "ja": "選手をスライドして配置するか、フィールドをタップしてください。マップを移動するには背景をスライドし、ズームするには2本の指でつまんでください。"
  },
