    "it": "I giocatori e la palla sono all'inizio della fase {v0}. Modifica i loro gesti per preparare la fase successiva. « Posizionamento iniziale » permette di regolare le posizioni di partenza.",
    "de": "Die Spieler und der Ball befinden sich am Start des Schrittes {v0}. Ändere ihre Bewegungen, um die nächste Phase vorzubereiten. „Anfangsaufstellung“ ermöglicht es, die Startpositionen einzustellen.",
    "pt": "Os jogadores e a bola estão no início da etapa {v0}. Modifica os seus gestos para preparar o seguinte. «Posicionamento inicial» permite ajustar as posições de partida.",
    "ja": "プレイヤーとボールはステップ{v0}の開始地点にいます。次の動きの準備のために動作を変更してください。「初期配置」でスタート位置を設定できます。"
