    "it": "Le posizioni di partenza seguono quelle delle partite. I tuoi spostamenti si applicano all'uscita dalla conquista.",
    "de": "Die Startpositionen folgen denen der Spiele. Deine Bewegungen gelten für den Ausgang der Eroberung.",
