  "ui.3ffa81d00d70": {
    "fr": "Chaque division démarre à 16 clubs et joue 30 jours, avec une coupe tirée au sort, montées, descentes et barrage. 5 000 Ovas au départ, doublons autorisés, packs Bronze, Argent et Or uniquement, aucun pack gratuit quotidien.",
    "en": "Each division starts with 16 clubs and plays for 30 days, with a randomly drawn cup, promotions, relegations, and playoff. 5,000 Ovas initially, duplicates allowed, Bronze, Silver, and Gold packs only, no daily free pack.",
    "es": "Cada división comienza con 16 clubes y juega 30 días, con una copa sorteada, ascensos, descensos y play-off. 5.000 Ovas al inicio, duplicados permitidos, solo paquetes Bronce, Plata y Oro, ningún paquete gratuito diario.",
    "it": "Ogni divisione parte con 16 club e gioca per 30 giorni, con una coppa sorteggiata, promozioni, retrocessioni e spareggi. 5.000 Ovas all'inizio, duplicati consentiti, solo pacchetti Bronzo, Argento e Oro, nessun pacchetto gratuito quotidiano.",
    "de": "Jede Division beginnt mit 16 Clubs und spielt 30 Tage, mit einem ausgelosten Pokal, Auf- und Abstiegen sowie Relegation. 5.000 Ovas zu Beginn, Duplikate erlaubt, nur Bronze-, Silber- und Gold-Packs, keine täglichen Gratis-Packs.",
    "pt": "Cada divisão começa com 16 clubes e joga durante 30 dias, com uma taça sorteada, subidas, descidas e playoff. 5.000 Ovas no início, duplicados permitidos, apenas pacotes Bronze, Prata e Ouro, nenhum pacote gratuito diário.",
    "ja": "各ディビジョンは16クラブで開始し、30日間プレイ、抽選カップ、昇格、降格、入れ替え戦あり。開始時に5,000 Ovas、重複可能、ブロンズ、シルバー、ゴールドパックのみ、無料デイリーパックなし"
  },
