  "ui.fd8717222ebd": {
    "fr": "Tout ce qui est fait ici reste dans ce laboratoire. Lance un match, déplace son horloge ou restaure une saison neuve sans toucher aux vraies ligues.",
    "en": "Everything done here stays in this laboratory. Start a match, move its clock, or restore a fresh season without affecting the real leagues.",
    "es": "Todo lo que se hace aquí se queda en este laboratorio. Lanza un partido, mueve su reloj o restaura una temporada nueva sin tocar las ligas reales.",
    "it": "Tutto ciò che viene fatto qui rimane in questo laboratorio. Avvia una partita, sposta il suo orologio o ripristina una stagione nuova senza toccare le vere leghe.",
    "de": "Alles, was hier gemacht wird, bleibt in diesem Labor. Starte ein Spiel, verschiebe seine Uhr oder stelle eine neue Saison wieder her, ohne die echten Ligen zu berühren.",
    "pt": "Tudo o que é feito aqui fica neste laboratório. Inicia uma partida, move o seu relógio ou restaura uma nova temporada sem tocar nas ligas reais.",
    "ja": "ここで行われるすべてのことはこのラボ内に留まります。試合を開始する、時計を動かす、または実際のリーグに触れずに新しいシーズンを復元することができます。"
  },
