  "ui.77fac752ae8e": {
    "fr": "Tu tentes le coup, et ça se retourne contre toi : le staff n’a pas apprécié.",
    "en": "You take a shot, and it backfires: the staff didn’t like it.",
    "es": "Lo intentas, y se vuelve en tu contra: al staff no le gustó.",
    "it": "Tentasti, e si è rivoltato contro di te: lo staff non ha apprezzato.",
    "de": "Du versuchst es, und es schlägt gegen dich zurück: das Personal war nicht zufrieden.",
    "pt": "Tentaste a sorte, e voltou-se contra ti: a equipa técnica não gostou.",
    "ja": "君は挑戦するが、それが裏目に出る：スタッフは気に入らなかった。"
  },
  "ui.5d15da4c00e4": {
    "fr": "Le message ne passe pas. Tu ravales ta réponse et la semaine se termine mal.",
    "en": "The message doesn’t get through. You swallow your reply and the week ends badly.",
    "es": "El mensaje no pasa. Tragaste tu respuesta y la semana termina mal.",
    "it": "Il messaggio non passa. Ingoi la tua risposta e la settimana finisce male.",
    "de": "Die Nachricht kommt nicht an. Du verschluckst deine Antwort und die Woche endet schlecht.",
    "pt": "A mensagem não passa. Engoles a tua resposta e a semana termina mal.",
    "ja": "メッセージは届かない。返答を飲み込み、一週間は悪い形で終わる。"
  },
  "ui.6b7f37e7e82e": {
    "fr": "Mauvais moment, mauvaise idée : tu en sors avec la tête basse.",
    "en": "Bad timing, bad idea: you walk away with your head down.",
    "es": "Mal momento, mala idea: sales con la cabeza baja.",
    "it": "Momento sbagliato, cattiva idea: ne esci a testa bassa.",
    "de": "Schlechter Moment, schlechte Idee: du gehst mit gesenktem Kopf davon.",
    "pt": "Momento errado, má ideia: sais com a cabeça baixa.",
    "ja": "悪いタイミング、悪い考え：頭を下げてそこから出る。"
  },
  "ui.5d5c21970035": {
    "fr": "Ça passe, sans plus. Personne n’en reparlera dans huit jours.",
    "en": "It's okay, nothing special. No one will talk about it in eight days.",
    "es": "Pasa, nada más. Nadie hablará de ello en ocho días.",
    "it": "Passa, senza più. Nessuno ne parlerà tra otto giorni.",
    "de": "Es geht so, nicht mehr. In acht Tagen wird niemand mehr darüber sprechen.",
    "pt": "Passa, sem mais. Ninguém vai falar disso dentro de oito dias.",
    "ja": "まあまあです、それ以上はありません。八日後には誰もそれについて話さないでしょう。"
  },
  "ui.0eaae174d26c": {
    "fr": "Tu t’en sors correctement, mais tu n’as convaincu personne.",
    "en": "You're doing alright, but you haven't convinced anyone.",
    "es": "Te las arreglas correctamente, pero no has convencido a nadie.",
    "it": "Te la cavi bene, ma non hai convinto nessuno.",
    "de": "Du kommst ganz gut zurecht, aber du hast niemanden überzeugt.",
    "pt": "Saíste-te razoavelmente, mas não convenceste ninguém.",
    "ja": "まずまずの出来ですが、誰も納得させられませんでした。"
  },
  "ui.95041b5f7411": {
    "fr": "Le vestiaire hausse les épaules : ni faute, ni exploit.",
    "en": "The locker room shrugs: neither a mistake nor an achievement.",
    "es": "El vestuario se encoge de hombros: ni falta, ni hazaña.",
    "it": "Lo spogliatoio alza le spalle: né colpa, né impresa.",
    "de": "Die Umkleide hebt die Schultern: weder Fehler noch Meisterleistung.",
    "pt": "O balneário encolhe os ombros: nem culpa, nem feito.",
    "ja": "ロッカールームは肩をすくめます：過失も特別な活躍もなし。"
  },
  "ui.9cd41f5f4b0f": {
    "fr": "Bien joué : le staff note, et ça se voit dans le groupe.",
    "en": "Well played: the staff take note, and it shows in the team.",
    "es": "Bien hecho: el personal lo nota, y se ve en el grupo.",
    "it": "Ben giocato: lo staff nota, e si vede nel gruppo.",
    "de": "Gut gespielt: das Team notiert es, und man sieht es in der Gruppe.",
    "pt": "Bem jogado: o staff nota, e isso vê-se no grupo.",
    "ja": "よくやった：スタッフは評価しており、それがチーム内にも見えます。"
  },
  "ui.bfdab1956b89": {
    "fr": "Tu tiens ta ligne et ça paie, on te regarde autrement cette semaine.",
    "en": "You stick to your line and it pays off, people look at you differently this week.",
    "es": "Mantienes tu línea y da resultado, te miran de otra manera esta semana.",
    "it": "Mantieni la tua linea e funziona, ti guardano diversamente questa settimana.",
    "de": "Du hältst deine Linie und es zahlt sich aus, diese Woche schaut man anders auf dich.",
    "pt": "Manténs a tua linha e isso paga-se, olham para ti de forma diferente esta semana.",
    "ja": "自分のラインを守り、それが報われています、今週は皆の見る目が変わります。"
  },
  "ui.723076462629": {
    "fr": "Le coup passe. Tu gagnes un peu de crédit dans le vestiaire.",
    "en": "The play goes through. You gain a bit of credit in the locker room.",
    "es": "El golpe pasa. Ganas un poco de crédito en el vestuario.",
    "it": "Il colpo passa. Guadagni un po' di credito nello spogliatoio.",
    "de": "Der Spielzug klappt. Du gewinnst ein wenig Kredit in der Umkleide.",
    "pt": "O lance passa. Ganas algum crédito no balneário.",
    "ja": "プレイは成功です。ロッカールームで少し信用を得ます。"
  },
