  "ui.2173c5e62fe3": {
    "fr": "Dernière minute, face aux poteaux... et tu la passes. Sang-froid total.",
    "en": "Last minute, in front of the posts... and you make it. Total coolness.",
    "es": "Último minuto, frente a los postes... y la pasas. Frío total.",
    "it": "Ultimo minuto, davanti ai pali... e tu la passi. Sangue freddo totale.",
    "de": "Letzte Minute, vor den Pfosten... und du triffst sie. Absolut cool.",
    "pt": "Último minuto, frente aos postes... e passas-na. Frieza total.",
    "ja": "試合終了間際、ゴールポストの前で…そして君が決める。冷静そのもの。"
  },
  "ui.b738dfaddc6e": {
    "fr": "Bras de fer tendu... mais tu obtiens gain de cause. Le vestiaire te regarde autrement.",
    "en": "Intense arm wrestle... but you get your way. The locker room looks at you differently.",
    "es": "Pulso tenso... pero logras tu objetivo. El vestuario te mira diferente.",
    "it": "Braccio di ferro teso... ma ottieni quello che volevi. Lo spogliatoio ti guarda in modo diverso.",
    "de": "Zähes Ringen... aber du bekommst, was du willst. Die Kabine schaut dich anders an.",
    "pt": "Braço de ferro esticado... mas consegues ganhar a causa. O balneário olha-te de forma diferente.",
    "ja": "力比べの末…でも君が勝ち取る。ロッカールームの見方が変わる。"
  },
  "ui.ae071c52e1cc": {
    "fr": "Tu tiens... jusqu’à la 60e où la blessure se rouvre. Plusieurs semaines dehors.",
    "en": "You hold on... until the 60th when the injury reopens. Several weeks out.",
    "es": "Aguantas... hasta el minuto 60 cuando la lesión se abre de nuevo. Varias semanas fuera.",
    "it": "Resisti... fino al 60° minuto quando la ferita si riapre. Diverse settimane fuori.",
    "de": "Du hältst durch... bis zur 60., wo die Verletzung wieder aufflammt. Mehrere Wochen raus.",
    "pt": "Aguentas... até aos 60 minutos, quando a lesão volta a abrir-se. Várias semanas fora.",
    "ja": "君は耐える…60分で怪我が再発。数週間は離脱。"
  },
  "ui.0dc7dd2ace3b": {
    "fr": "Tu dis oui à ton agent. Il décroche son téléphone, et les propositions arrivent, à toi de choisir.",
    "en": "You say yes to your agent. He picks up the phone, and the offers start coming in, time to choose.",
    "es": "Dices sí a tu agente. Él toma el teléfono, y llegan las ofertas, a ti te toca elegir.",
    "it": "Dici sì al tuo agente. Prende il telefono e le proposte arrivano, sta a te scegliere.",
    "de": "Du sagst ja zu deinem Agenten. Er greift zum Telefon, und die Angebote kommen – jetzt liegt die Wahl bei dir.",
    "pt": "Dizes sim ao teu agente. Ele pega no telemóvel, e as propostas chegam, cabe-te a ti escolher.",
    "ja": "エージェントにイエスと言う。彼が電話を取り、オファーが次々と来る。君が選ぶ番だ。"
  },
