  "ui.c75f34bd6d59": {
    "fr": "Tu prends un jeune du centre de formation sous ton aile. Les séances vidéo remplacent les fins de soirée : ton corps te dit merci, et le vestiaire te regarde autrement.",
    "en": "You take a youth from the training center under your wing. Video sessions replace late-night outings: your body says thanks, and the locker room sees you differently.",
    "es": "Tomas a un joven del centro de formación bajo tu ala. Las sesiones de video reemplazan las noches de salida: tu cuerpo te lo agradece, y el vestuario te mira de otra manera.",
    "it": "Accogli un giovane del centro di formazione sotto la tua ala. Le sessioni video sostituiscono le serate: il tuo corpo ti ringrazia e lo spogliatoio ti guarda diversamente.",
    "de": "Du nimmst einen Jugendlichen aus dem Ausbildungszentrum unter deine Fittiche. Die Videoeinheiten ersetzen die späten Abende: Dein Körper sagt danke, und die Kabine schaut dich anders an.",
    "pt": "Tu apanhas um jovem da academia de formação debaixo da tua asa. As sessões de vídeo substituem as noites tardias: o teu corpo agradece, e o balneário olha-te de outra forma.",
    "ja": "あなたは育成センターの若手を自分の翼の下に迎え入れます。ビデオセッションが夜の遅くまでの練習に取って代わります：体が感謝を伝え、ロッカールームの雰囲気も変わります。"
  },
